int firstTrue(int lo, int hi, bool Function(int) test) {
  var ans = hi + 1;
  while (lo <= hi) {
    final mid = lo + (hi - lo) ~/ 2;
    if (test(mid)) {
      ans = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }
  return ans;
}

